window.MONSTER_CHUNK_111 = [{"name":"Archer Bush","cr":2,"xp":600,"alignment":"N","size":"Small","type":"plant","init":0,"senses":[{"type":"tremorsense","modifier":"60 ft."}],"ac":14,"ac_touch":11,"ac_flat_footed":14,"ac_mods":"+3 natural, +1 size","hp":21,"hd":"3d8+9","hdvalue":3,"fort":6,"ref":1,"will":1,"immunities":["plant traits"],"speed":[{"type":"land","speed":10}],"ranged":"thorns +4 (1d8)","space":"5 ft.","reach":"5 ft.","strength":11,"dexterity":10,"constitution":16,"intelligence":2,"wisdom":11,"charisma":9,"baseatk":2,"cmb":1,"cmd":11,"cmd_special":"can't be tripped","feats":[{"feat":"Skill Focus (Stealth)"},{"feat":"Weapon Focus (thorns)"}],"skills":[{"skill":"Stealth","value":13}],"environments":["any underground"],"organizations":["solitary","patch (4-8)","colony (11-20)"],"treasure":"none","description_visual":"This creature looks like a small mound of brownish-green leaves. From its trunk sprout several thick branches, each covered sparsely with leaves, and each sporting rows of needle-like thorns. The leaves have small pale buds of gold and purple.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Thorns","kind":"Ex","details":"An archer bush can loose a cluster of needlesharp thorns at a single target within 20 ft. as a standard action. An opponent hit by the thorns takes 1d8 points of piercing damage. Further, the target takes a -1 circumstance penalty on attack rolls, saves, and checks until the thorns are removed (full-round action to remove the thorns)."}],"description":"The archer bush is a subterranean, semi-mobile plant that gains sustenance from the blood of living creatures. Hidden beneath its trunk is the archer bush's mouth, which appears to be nothing more than a dark recess or cavity.\n\nAn archer bush attacks by firing a cluster of thorns at any creature that comes within 20 ft. of its location.","ecology":"","habitat_society":"","credit":"The Archer Bush originally appeared in the module B3 Palace of the Silver Princess (© TSR/Wizards of the Coast, 1981) and is used by permission."},{"name":"Axe Beak","cr":2,"xp":600,"alignment":"N","size":"Large","type":"animal","init":3,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":14,"ac_touch":12,"ac_flat_footed":11,"ac_mods":"+3 Dex, +2 natural, -1 size","hp":22,"hd":"3d8+9","hdvalue":3,"fort":6,"ref":6,"will":1,"speed":[{"type":"land","speed":50}],"melee":"bite +4 (1d6+3) and 2 claws +4 (1d4+3)","space":"10 ft.","reach":"10 ft.","strength":16,"dexterity":17,"constitution":16,"intelligence":2,"wisdom":11,"charisma":10,"baseatk":2,"cmb":6,"cmd":19,"feats":[{"feat":"Run"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":9}],"environments":["temperate plains"],"organizations":["solitary","pair","flock (3-6)"],"treasure":"none (eggs are worth 50-80 gp each)","description_visual":"This creature resembles a large ostrich with a strong, thick neck and sharpened beak. Its neck is covered in white feathers, and its body is covered in black feathers with a white underbelly and tail. Its legs are covered in yellow scales.","source":"Tome of Horrors Complete (3pp)","description":"The axe beak is a prehistoric flightless, carnivorous bird that resembles a 7-foot tall ostrich. It is an aggressive hunter and has a strong, thick neck and a sharp beak. The axe beak makes a honking noise that can be heard clearly up to one-half mile away. An axe beak lair contains 1d4 eggs worth 50-80 gp each. Hatchlings fetch the same value on the market.\n\nThe axe beak attacks by kicking with its clawed ft. and biting with its beak. It is a very aggressive hunter and runs down its prey should an opponent flee. If extremely hungry, an axe beak attacks until it or its prey is dead.","ecology":"","habitat_society":"","credit":"The Axe Beak originally appeared in the First Edition Monster Manual (© TSR/Wizards of the Coast, 1977) and is used by permission."},{"name":"Baboonwere","cr":2,"xp":600,"alignment":"CE","size":"Medium","type":"magical beast","subtypes":["shapechanger"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":16,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+2 armor, +3 Dex, +1 natural","hp":15,"hd":"2d10+4","hdvalue":2,"fort":5,"ref":6,"will":1,"dr":"5/cold iron","speed":[{"type":"land","speed":30}],"melee":"longsword +5 (1d8+1), bite +0 (1d6 plus disease) or bite +5 (1d6+1 plus disease)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"weapon intuition"}],"strength":13,"dexterity":17,"constitution":14,"intelligence":11,"wisdom":12,"charisma":12,"baseatk":2,"cmb":3,"cmd":16,"feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":5},{"skill":"Bluff","value":4},{"skill":"Climb","value":3},{"skill":"Perception","value":5},{"skill":"Stealth","value":7},{"skill":"Survival","value":4}],"languages":["Common"],"sq":[{"type":"baboon empathy"},{"type":"change shape"}],"environments":["warm forests","warm plains"],"organizations":["solitary","pair","gang (1-2 plus 6-10 baboons)","troop (3-6 plus 10-20 baboons)"],"treasure":"standard (leather armor, longsword)","description_visual":"This lithe creature has the head of a baboon, a fur-covered body, and sharpened fangs that glisten with fresh blood.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Baboon Empathy","kind":"Ex","details":"A baboonwere can communicate and empathize with baboons, and can use Bluff as if it were Diplomacy to change a baboon's attitude, receiving a +4 racial bonus to do so."},{"type":"Change Shape","kind":"Su","details":"A baboonwere has three forms. Its natural form is that of a baboon, but it can also take the form of a human or human-baboon hybrid. A baboonwere's human form is fixed-it cannot assume different human forms. A baboonwere can only use its diseased bite in hybrid or baboon form. In baboon form, it functions as a baboon. In its hybrid form, a baboonwere can make a bite attack as a secondary attack, while in human form it lacks its bite entirely. A baboonwere can shift into any of its three alternate forms as a move action. Equipment doesn't meld with the new form between human and hybrid forms but does between those forms and its baboon form."},{"type":"Disease","kind":"Ex","details":"Filth Fever: Bite-injury; save DC 13 Fort; onset 1d3 days; frequency 1/day; effect 1d3 Dex damage and 1d3 Con damage; cure 2 consecutive saves. The save DC is Constitution-based."},{"type":"Weapon Intuition","kind":"Ex","details":"A baboonwere is proficient with simple and martial melee weapons."}],"description":"Baboonweres are evil baboons born with the ability to assume human or hybrid human form. Baboonweres are most often found among normal baboons, though some prefer to maintain their human form and live amongst ordinary people in small towns and villages. Usually when the livestock and cattle begin turning up missing or slain is when the baboonwere moves on, before the finger of suspicion is pointed its way.\n\nIn its hybrid form, a baboonwere stands just over 5 ft. tall and weighs roughly 130 pounds. Its hair tends to be either light brown or dark brown. Eyes are always brown.\n\nBaboonweres fight with weapons, usually longswords, short swords, and spears or crossbows and a diseased bite. Slain foes are dragged back to their lairs and eaten at the baboonwere's leisure.\n\nBaboonweres are frequently found among normal baboons and are indistinguishable from them when in animal form.","ecology":"","habitat_society":""},{"name":"Banderlog","cr":2,"xp":600,"alignment":"N","size":"Medium","type":"monstrous humanoid","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":14,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+2 Dex, +2 natural","hp":19,"hd":"3d10+3","hdvalue":3,"fort":2,"ref":5,"will":4,"speed":[{"type":"land","speed":40},{"type":"climb","speed":30}],"melee":"bite +5 (1d6+2) or club +5 (1d6+2)","ranged":"coconut +6 (1d4+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"coconut throwing"}],"strength":15,"dexterity":14,"constitution":12,"intelligence":8,"wisdom":12,"charisma":6,"baseatk":3,"cmb":5,"cmd":17,"feats":[{"feat":"Alertness"},{"feat":"Weapon Focus (coconut)"}],"skills":[{"skill":"Climb","value":10},{"skill":"Perception","value":9},{"skill":"Sense Motive","value":3},{"skill":"Stealth","value":8},{"skill":"Survival","value":7}],"languages":["Banderlog","Common"],"environments":["warm forests"],"organizations":["gang (2-5)","pack (6-24 plus 1-2 6 HD leaders)"],"treasure":"none","description_visual":"This creature appears as a short, baboon-like creature with grayish brown fur.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Coconut Throwing","kind":"Ex","details":"A banderlog can hurl a coconut up to 10 ft. (range increment 10 ft., maximum range 50 ft.)."}],"description":"The banderlog is a somewhat intelligent baboon-like primate that makes its home in warm forests and jungles. Though it appears as a larger version of the common baboon, it doesn't keep company with or associate with normal baboons. Banderlogs' intelligence allows them to form small tribal communities for protection and companionship. The leader of such a community is usually the largest and strongest banderlog of the tribe. It isn't uncommon to find more than one tribe in the same area. Banderlogs generally coexist quite well with other banderlog tribes, though if food becomes scarce, they attempt to drive off all other tribes in the area. Banderlogs sustain themselves on a diet of fruits and nuts, with coconuts being their favorite food. Though omnivorous, they rarely eat meat of any sort. The typical banderlog stands just over 4-ft. tall and weighs about 100 pounds. Banderlogs are non-aggressive unless they are threatened. They prefer to attack opponents from a distance using small rocks or coconuts to hit their foes. Should they be engaged in melee, they attack using a vicious bite.","as_character":[{"description":"Banderlogs have racial Hit Dice and can have class levels. Most banderlogs are barbarians or rangers. Most banderlog spellcasters are adepts. Banderlog characters possess the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+4 Strength, +4 Dexterity, +2 Constitution, -2 Intelligence, +2 Wisdom, -4 Charisma: Banderlogs are strong and hardy tree dwellers, but also shy and retiring."},{"type":"Base Speed","value":"A banderlog's base land speed is 40 ft. Its base climb speed is 30 ft."},{"type":"Darkvision","value":"Banderlogs can see in the dark up to 60 ft."},{"type":"Racial Hit Dice","value":"A banderlog begins with three levels of monstrous humanoid, which provide 3d10 Hit Dice, a base attack bonus of +3, and base saves of Fort +1, Ref +3, and Will +3."},{"type":"Racial Skills","value":"A banderlog's monstrous humanoid levels give it skill points equal to 3 x (4 + Int modifier, minimum 1) Racial Feats: A banderlog's monstrous humanoid levels give it two feats."},{"type":"AC","value":"Banderlogs have +2 natural armor bonus."},{"type":"Natural Weapons","value":"Banderlogs can fight with a bite (1d6)."},{"type":"Special Attacks","value":"Coconut throwing."},{"type":"Languages","value":"Banderlogs begin plays speaking Banderlog. Banderlogs with high Intelligence scores can choose from the following bonus languages: Common, Elven, Gnome, Halfling, Sylvan."}]}],"ecology":"","habitat_society":"","credit":"The Banderlog originally appeared in the First Edition module S3 Expedition to the Barrier Peaks (© TSR/Wizards of the Coast, 1980) (as the baboonoid) and later in the First Edition Monster Manual II (© TSR/ Wizards of the Coast, 1983) and is used by permission."},{"name":"Blindheim","cr":2,"xp":600,"alignment":"CE","size":"Small","type":"aberration","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":16,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+1 Dex, +4 natural, +1 size","hp":18,"hd":"4d8","hdvalue":4,"fort":1,"ref":2,"will":5,"speed":[{"type":"land","speed":30}],"melee":"bite +5 (1d8)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"eye beams"}],"strength":10,"dexterity":12,"constitution":11,"intelligence":2,"wisdom":12,"charisma":6,"baseatk":3,"cmb":2,"cmd":13,"feats":[{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Perception","value":11},{"skill":"Stealth","value":10},{"skill":"Survival","value":5}],"environments":["any underground"],"organizations":["solitary","gang (2-4)"],"treasure":"standard","description_visual":"This creature is a 4-foot tall frog-like humanoid with large, bulbous eyes that constantly emits bright yellow beams of light. Its skin is mottled yellow, growing darker across its back. Its ft. are webbed as are its claws.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Eye Beams","kind":"Ex","details":"When a blindheim's eyes are open, it emits a 30-foot cone of light. It can see normally in this light and functions normally in areas of darkness (but not deeper darkness). A creature looking at a blindheim when its eye beams are \"on\" must succeed on a DC 12 Fortitude save or be blinded for 1 hour. A successful save renders the creature immune to the same blindheim's eye beams for 24 hours. The blindness can be cured by remove blindness or more powerful magic. The save DC is Constitution-based."}],"description":"Blindheims dwell in underground caverns and sustain themselves on a diet of funguses, molds, and small rodents. An extra eyelid allows the blindheim to \"turn off\" its eyes when it is sleeping or resting. A dead blindheim's eyes are dull gold in color. Blindheims are 4 ft. tall and weigh about 150 pounds. A blindheim attacks by first blinding a foe with its gaze and then rushing in to use its bite attack. It can turn its eyes on and off as it wishes, but always leaves them on during combat. If overmatched, a blindheim flees.","ecology":"","habitat_society":"","credit":"The Blindheim originally appeared in the First Edition Fiend Folio (© TSR/Wizards of the Coast, 1981) and is used by permission."},{"name":"Bone Delver","cr":2,"xp":600,"alignment":"CE","size":"Medium","type":"undead","init":3,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["grave light (10 ft.)"],"ac":16,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+3 Dex, +3 natural","hp":13,"hd":"2d8+4","hdvalue":2,"hp_mods":["fast healing 2"],"fort":2,"ref":3,"will":4,"immunities":["undead traits"],"speed":[{"type":"land","speed":30}],"melee":"shovel +4 (1d6+1 plus disease) or 2 claws +4 (1d4+1 plus disease)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"grave light"},{"type":"scream of agony"}],"strength":13,"dexterity":16,"intelligence":10,"wisdom":13,"charisma":14,"baseatk":1,"cmb":2,"cmd":15,"feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Disable Device","value":9},{"skill":"Knowledge (local)","value":2},{"skill":"Perception","value":6},{"skill":"Stealth","value":10}],"languages":["Common"],"sq":[{"type":"shovel"}],"environments":["any land"],"organizations":["solitary","crew (2-5)"],"treasure":"standard (shovel, bone delver's lantern, thieves' tools)","description_visual":"This rotting humanoid wears tattered rags that hang loosely about its twisted and hunched form. Its face is twisted into a visage of pain and rage, and its clawed hands clutch the tools of its trade-a shovel and a lantern that glows with an eerie red hue.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Disease","kind":"Ex","details":"Filth Fever: claws or shovel-injury; save DC 13 Fort; onset 1d3 days; frequency 1/ day; effect 1d3 Dex damage and 1d3 Con damage; cure 2 consecutive saves. The save DC is Charisma-based."},{"type":"Grave Light","kind":"Su","details":"A bone delver's lantern sheds light in a 10-foot radius. Living creatures within the area take 1 point of damage each round. Additionally, a bone delver's fast healing only works when it is within 10 ft. of its lantern. The lantern can be extinguished with a bless spell (it relights after 1 hour) or attacked and destroyed (hardness 5, hp 10). This lantern functions only for the bone delver to which it belongs. In the hands of living creatures it functions differently."},{"type":"Scream of Agony","kind":"Su","details":"A bone delver can unleash a bone-chilling shriek that affects all who hear it within 30 ft. An affected creature must make a DC 13 Will save or be shaken for 1d4+2 rounds. Creatures with more than 4 HD are unaffected by this attack. Creatures that successfully save are immune to the scream of agony of that bone delver for one day. The save DC is Charisma-based. Shovel A bone delver suffers no penalties on attack rolls when wielding a shovel as a weapon."}],"description":"Cemeteries and graveyards are well known for their concentration of negative energy and it is this, rather than the mere presence of the buried dead, that can cause all manner of creatures to rise from their graves to haunt the living. A few braves souls make their gruesome livelyhood by preying on graves, digging up the treasures and riches sometimes laid to rest with their owners. Thes graverobbers are detested by most civilized societies for their callous nature, and all too often would be graverobbers fall foul to the unliving denizens of the graveyard.\n\nBone delvers were in life graverobbers that died whilst performing their nefarious tasks. Some may have inadvertently awoken undead creatures in their graves, others were outwitted by cunning traps placed in well protected mausoleums. Bone delvers usually appear as hunched, shambling humanoids with faces twisted into a visage of pain and rage. They visibly carry the wounds that caused their demise. Bone delvers forever carry the tools of their trade-a lantern and a shovel, though lockpicks are also commonly found on their walking corpses. The lantern still burns, though with an unnatural and eerie red glowing light.\n\nA bone delver initiatiate its attack by uttering a chilling scream of terribly agony, rage, and frustration that transcensds death itself. Those not affected by the scream are made targets of melee attacks with the creature's shovel or filthy claws.","ecology":"","habitat_society":""},{"name":"Buckawn","cr":2,"xp":600,"alignment":"N","size":"Small","type":"fey","init":3,"senses":[{"type":"low-light vision"}],"ac":17,"ac_touch":15,"ac_flat_footed":13,"ac_mods":"+3 Dex, +1 dodge, +2 natural, +1 size","hp":11,"hd":"3d6","hdvalue":3,"fort":1,"ref":6,"will":4,"dr":"5/cold iron","sr":13,"speed":[{"type":"land","speed":30}],"melee":"dagger +5 (1d3 plus poison)","ranged":"dart +5 (1d3 plus poison)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":3,"spell_like_abilities_concentration":3,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"dancing lights"},{"spell":"disguise self"},{"spell":"ghost sound"},{"spell":"invisibility","details":"self only"}]},{"frequency":"1/day","spells":[{"spell":"entangle"},{"spell":"insect plague","details":"one swarm only"},{"spell":"pass without trace"}]}],"strength":10,"dexterity":17,"constitution":11,"intelligence":12,"wisdom":13,"charisma":14,"baseatk":1,"cmb":0,"cmd":14,"feats":[{"feat":"Dodge"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Bluff","value":8},{"skill":"Craft (alchemy)","value":7,"special":"+9 when making poison"},{"skill":"Escape Artist","value":9},{"skill":"Knowledge (nature)","value":7},{"skill":"Perception","value":9},{"skill":"Sense Motive","value":7},{"skill":"Stealth","value":13}],"languages":["Common","Sylvan"],"sq":[{"type":"poison use"}],"environments":["temperate forests"],"organizations":["gang (2-4)","band (6-11)","tribe (12-20)"],"treasure":"incidental","description_visual":"This creature is a halfling-sized humanoid with swarthy skin and dark hair. Its eyes are greenish-brown and its clothes are brown.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Poison Use","kind":"Ex","details":"Buckawns never risk accidentally poisoning themselves when applying poison to a blade. They favor moonseed berries as poison and usually have a plentiful supply readily available. These small berries are bluish-purple and resemble wild grapes. They are highly poisonous and are often mixed with food or crushed and smeared on a weapon or object. Moonseed Berries: poison-contact or ingested; save Fort DC 13; frequency 1/round for 4 rounds; effect 1d2 Con; cure 1 save; Price 1,500 gp."}],"description":"Buckawns are somehow related to brownies, but they are nowhere near as kind-hearted and playful. Buckawns are extremely reclusive and rarely have dealings with outside races. Trade of any kind between a buckawn tribe and another race is virtually unheard of.\n\nCharacters who journey into a buckawn's realm are usually left alone, providing they themselves leave the buckawn's realm alone. Trespassers, evil-doers, and those that disturb the natural beauty of a buckawn domain are dealt with quickly-and permanently if necessary.\n\nA buckawn stands about 2 ft. tall and weighs about 30 pounds.\n\nBuckawns favor daggers and darts in combat. They readily use poisoned blades when confronted with a tough opponent, when outnumbered, or when battling opponents for whom they have great disdain.","ecology":"","habitat_society":"","credit":"The Buckawn originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Burrowing Lamprey","cr":2,"xp":600,"alignment":"N","size":"Small","type":"magical beast","subtypes":["aquatic"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":15,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+2 Dex, +2 natural, +1 size","hp":8,"hd":"1d10+3","hdvalue":1,"fort":5,"ref":4,"will":1,"speed":[{"type":"land","speed":5},{"type":"swim","speed":30}],"melee":"bite +4 (1d4 plus attach plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"attach"},{"type":"flesh burrow"},{"type":"poison"}],"strength":10,"dexterity":15,"constitution":16,"intelligence":1,"wisdom":12,"charisma":2,"baseatk":1,"cmb":0,"cmb_special":"+8 vs. grapple when attached","cmd":12,"cmd_special":"can't be tripped","feats":[{"feat":"Improved Initiative"},{"feat":"Weapon Finesse","type":"bonus"}],"skills":[{"skill":"Escape Artist","value":10},{"skill":"Perception","value":5},{"skill":"Swim","value":8}],"sq":[{"type":"amphibious"}],"environments":["temperate aquatic","warm aquatic"],"organizations":["cluster (2-5)","swarm (6-20)"],"treasure":"none","description_visual":"This eel-like creature has leathery-looking skin almost black in color. No discernible features are present on its form.","group":"Lamprey","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Attach","kind":"Ex","details":"When a burrowing lamprey hits with a bite attack, its suckered mouth latches onto the target, anchoring it in place. An attached burrowing lamprey is effectively grappling its prey. The burrowing lamprey loses its Dexterity bonus to AC and has an AC of 13, but holds on with great tenacity. A burrowing lamprey has a +8 racial bonus to maintain its grapple on a foe once it is attached. An attached burrowing lamprey can be struck with a weapon or grappled itself-if its prey manages to win a grapple check or Escape Artist check against it, the burrowing lamprey is removed."},{"type":"Flesh Burrow","kind":"Ex","details":"At the start of its next turn, the round after it attaches to its prey, a burrowing lamprey burrows into the target's flesh and subjects it to its poison. Applying flame to the point of entry deals 1d6 points of fire damage to both the host and the burrowing lamprey. Cutting the lamprey out works, but the longer the lamprey remains in the host, the more damage this method does. Cutting a lamprey out requires a slashing weapon and a DC 20 Heal check, and deals 1d6 points of damage to the host per round the lamprey has been inside it. If the Heal check succeeds, one lamprey is removed. Remove disease instantly kills any burrowing lampreys inside a host."},{"type":"Poison","kind":"Ex","details":"Flesh burrow-injury; save DC 14 Fort; effect 1d2 Constitution damage; cure -. The save DC is Constitution-based. The lamprey's poison liquefies the host's organs. A successful saving throw can prevent Con damage for that round, but the only cure is to remove the burrowing lamprey from the host."}],"description":"The burrowing lamprey is an eel-like fish that attaches to its prey, and then burrows into its body, feasting on blood and the rich vital organs. They are a danger to fish and aquatic mammals, and can be as deadly as a school of piranha when encountered in large numbers. Burrowing lampreys resemble eels three to four ft. long, with sphincter-like mouths positioned within hardened cartilaginous beaks.\n\nAlthough they are usually marine creatures, burrowing lampreys breed in coastal freshwater swamps and rivers, and thus can be found in both fresh and saltwater environments.\n\nThey prefer to either ambush prey by hiding along the ocean floor or in rocky crevices, or swarm around a target if traveling in numbers. However, it is possible that they can be encountered inside a dead creature's remains, feeding on its vital organs.\n\nMedium- and large-sized burrowing lampreys are less common, but sometimes found in the deeper sea, where they may attack large sharks or even small whales.\n\nBurrowing lampreys seek out targets at least equal to their size category, and up to three sizes larger, if they can, though a starving lamprey attacks just about anything. They attack with their bite, then immediately attempt to burrow into their victim.","ecology":"","habitat_society":""},{"name":"Cadaver","cr":2,"xp":600,"alignment":"CE","size":"Medium","type":"undead","init":5,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":13,"ac_touch":11,"ac_flat_footed":12,"ac_mods":"+1 Dex, +2 natural","hp":16,"hd":"2d8","hdvalue":2,"hp_mods":["reanimation"],"fort":0,"ref":1,"will":3,"dr":"5/bludgeoning","immunities":["cold","undead traits"],"speed":[{"type":"land","speed":30}],"melee":"2 claws +2 (1d4+1 plus disease) and bite +2 (1d6+1  plus disease)","space":"5 ft.","reach":"5 ft.","strength":13,"dexterity":13,"wisdom":10,"charisma":10,"baseatk":1,"cmb":2,"cmd":13,"feats":[{"feat":"Improved Initiative","type":"bonus"}],"environments":["any"],"organizations":["solitary","gang (2-5)"],"treasure":"standard","description_visual":"This monster resembles a humanoid dressed in tattered rags. Rotted flesh reveals corded muscles and sinew stretched tightly over its skeleton. Hollow eye sockets flicker with a hellish glow. Broken and rotted teeth line its mouth, and its hands end in wicked claws.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Disease","kind":"Ex","details":"Filth fever: Claw and bite-injury; save Fort DC 11; onset 1d3 days; frequency 1/day; effect 1d3 Dex damage and 1d3 Con damage; cure 2 consecutive saves. The save DC is Charisma-based."},{"type":"Reanimation","kind":"Su","details":"When reduced to 0 hit points or less, a cadaver isn't destroyed; rather it falls inert and begins the process of reanimating by regaining 1 hit point per round. Hit points lost to magical weapons or spells are not regained. When the creature reaches its full hit point total (minus damage dealt by magical attacks and weapons), it stands up, ready to fight again. If the creature is destroyed by channeled positive energy, it cannot reanimate. If a cleric casts gentle repose on the cadaver when it is reduced to 0 hit points, it cannot reanimate. A bless spell delays the reanimation, causing the creature to regain hit points at half the normal rate (i.e. 1 hit point every other round)."}],"description":"Cadavers are the undead skeletal remains of people who have been buried alive or given an improper burial (an unmarked grave or mass grave for example). They can be found haunting graveyards and cemeteries.\n\nCadavers are infused with a hatred that rivals many other undead creatures. This hatred includes its own existence as well as the existence of all living creatures. Thus, the cadaver attacks all creatures it encounters.\n\nThey have a distinct hatred for light, but it doesn't damage them. All encounters with cadavers are at night or places cloaked in darkness.\n\nEncounters are most often with a solitary creature. Multiple cadavers don't work in concert with each other; being mindless they simply charge into combat, killing all creatures they can. Cadavers are sometimes found in the employ of greater undead (such as wights or ghasts).\n\nA cadaver attacks by raking with its filthy claws or biting with its sharp, disease-infested teeth. They often lie in shallow graves waiting for potential victims to wander too close, where they immediately spring to the attack, raking and biting until destroyed or until all foes are dead.","ecology":"","habitat_society":""},{"name":"Cave Fisher","cr":2,"xp":600,"alignment":"N","size":"Medium","type":"vermin","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":11,"ac_flat_footed":14,"ac_mods":"+1 Dex, +4 natural","hp":22,"hd":"3d8+9","hdvalue":3,"fort":6,"ref":2,"will":1,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":20},{"type":"climb","speed":20}],"melee":"2 claws +5 (1d4+3)","ranged":"filament +3 (drag)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"pull","details":"filament, 10 ft."}],"strength":17,"dexterity":12,"constitution":17,"wisdom":10,"charisma":4,"baseatk":2,"cmb":5,"cmb_special":"+4 vs. with pull","cmd":16,"cmd_special":"+12 vs. trip","skills":[{"skill":"Climb","value":11}],"environments":["any underground"],"organizations":["solitary","gang (2-4)"],"treasure":"standard","description_visual":"This man-sized creature resembles a cross between a lobster and a spider. It has eight legs, two of which end in serrated pincers. Its snout is long and pointed.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Filament","kind":"Ex","details":"A cave fisher can fire a thin filament of sticky silk as a standard action. This touch attack has a range of 60 ft. and no range increment. A creature struck by a cave fisher's filament becomes attached to the sticky thread. As a standard action, a creature can rip the filament free with a DC 20 Strength check. A caught creature can also attempt to escape a filament by making a DC 25 Escape Artist check. A filament is AC 14 (touch 12), has 5 hit points, and has DR 15/slashing. An application of liquid with high alcohol content (or a dose of universal solvent) dissolves the adhesive and releases the creature caught by the filament. A cave fisher can have only one filament active at a time."}],"description":"The cave fisher lairs on ledges and cliffs underground, where it can quickly strike and reel in its prey. Its lair is always littered with bones and gear from its previous victims. The cave fisher is a 7-foot long insect-like creature with a hard outer shell. The cave fisher's snout fires a strong, web-like adhesive filament it uses to reel in its prey. Often, the ground and walls nearby are covered with this filament.\n\nThe cave fisher's preferred method of attack is to anchor itself to its ledge and string its filament across the ground of its lair. When a living creature touches or passes near the filament, the fisher attempts to trap it and reel it in. If the cave fisher fails this, it can fire its filament at an opponent up to 60 ft. away. Another favored method of attack for the cave fisher is to secret itself in a crack or a ledge above a cavern and dangle its filament down onto unsuspecting creatures passing below it (DC 20 Perception check to notice the filament).","ecology":"","habitat_society":"","credit":"The Cave Fisher originally appeared in the First Edition module A4 In the Dungeons of the Slave Lords (© TSR/Wizards of the Coast, 1981) and later in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Cave Moray","cr":2,"xp":600,"alignment":"N","size":"Medium","type":"magical beast","init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"tremorsense","modifier":"60 ft."}],"ac":15,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+3 Dex, +2 natural","hp":19,"hd":"3d10+3","hdvalue":3,"fort":4,"ref":6,"will":2,"speed":[{"type":"land","speed":20}],"melee":"bite +5 (2d6+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"ambush"},{"type":"recoil attack"}],"strength":14,"dexterity":17,"constitution":13,"intelligence":2,"wisdom":13,"charisma":10,"baseatk":3,"cmb":5,"cmd":18,"feats":[{"feat":"Skill Focus (Perception, Stealth)"}],"skills":[{"skill":"Perception","value":9},{"skill":"Stealth","value":10,"special":"+14 in rocky or stony areas"}],"environments":["any underground"],"organizations":["cluster (4-6)","colony (7-16)"],"treasure":"none","description_visual":"The creature is a brownish-gray, slug-like creature about 5 ft. long and 1 foot thick. Its eyes are dark brown and bulbous.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Ambush","kind":"Ex","details":"If a cave moray surprises its opponent, it gains a +4 circumstance bonus to its attack roll for that round."},{"type":"Recoil Attack","kind":"Ex","details":"A cave moray lunges out of its cyst up to 5 ft. to strike at passing opponents or prey. This attack is swift enough to attack running or flying creatures. A cave moray's recoil attack is always considered a charge attack since it recoils into its cyst after an attack to lunge at its opponent again."}],"description":"Cave morays make their lairs underground in abandoned mines, dungeons, or natural occurring caves, usually near corridors, hallways or other areas of high traffic. Its lair is a burrow, just large enough for its body dug into the walls. Only one cave moray inhabits each burrow.\n\nA typical cave moray cluster contains an equal number of males and females, while a colony is often contains more females than males.\n\nEven so, the male cave moray dominates the colony. Mating occurs in the warmer months of the year with a gestation period of about 6 months. Young are born live and depend completely on their mother for nourishment and food until they are about 8 months old.\n\nA cave moray is a carnivore and its diet consists of whatever it can kill. Prey is devoured immediately and never stored or saved for later. A typical adult cave moray can go a month or more without eating.\n\nA cave moray's favored tactic is to lie in wait in its cyst-like burrow in the wall and attack whenever prey passes nearby. Two or more cave morays usually strike in unison, one from each side of a passage. After an attack, a cave moray recoils into its cyst to strike again.","ecology":"","habitat_society":"","credit":"The Cave Moray originally appeared in the First Edition module S4 Lost Caverns of Tsojcanth (© TSR/Wizards of the Coast, 1982) and later in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission. Cave morays made their first appearance in d20 in the Necromancer Games module Tomb of Abysthor by Clark Peterson (©2001, Clark Peterson, Necromancer Games, Inc.)."},{"name":"Chike","cr":2,"xp":600,"alignment":"NE","size":"Large","type":"humanoid","subtypes":["reptilian"],"init":0,"senses":[{"type":"low-light vision"}],"ac":11,"ac_touch":9,"ac_flat_footed":11,"ac_mods":"+2 natural, -1 size","hp":30,"hd":"4d8+12","hdvalue":4,"fort":7,"ref":1,"will":1,"speed":[{"type":"land","speed":30},{"type":"swim","speed":30}],"melee":"battleaxe +6 (2d6+4), bite +1 (1d8+2) or 2 claws +6 (1d6+4), bite +6 (1d8+4)","space":"10 ft.","reach":"10 ft.","strength":18,"dexterity":11,"constitution":16,"intelligence":7,"wisdom":10,"charisma":11,"baseatk":3,"cmb":8,"cmd":18,"feats":[{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":8},{"skill":"Stealth","value":-2,"special":"+6 in water"},{"skill":"Swim","value":13}],"languages":["Chike"],"sq":[{"type":"crocodile empathy"},{"type":"hold breath"}],"environments":["any rivers","temperate marshes","warm marshes"],"organizations":["solitary","pair","raiding party (3-6 plus 2-3 crocodiles)","band (7-12)","tribe (20-40 plus 4-6 crocodiles plus 1-2 dire crocodiles)"],"treasure":"standard (battleaxe)","description_visual":"This green-scaled reptilian humanoid is powerfully built and has the head of a crocodile.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Crocodile Empathy","kind":"Ex","details":"A chike can communicate and empathize with crocodiles and dire crocodiles. They can use Diplomacy to alter such an animal's attitude, and when doing so gain a +4 racial bonus on the check."},{"type":"Hold Breath","kind":"Ex","details":"A chike can hold its breath for a number of rounds equal to 4 times its Constitution score before it risks drowning."}],"description":"Chike are savage crocodilian humanoids (called Crocfolk by other races) that make their homes deep within swamps and marshlands. They are believed to be descended from or related to actual crocodiles, though scholars cannot find a link between the two somewhat related creatures. Chike usually live in small tribal villages of up to 40 individuals led by a tribal leader (usually the strongest of the group). Buildings are constructed of whatever natural resources and materials the chike can find. Larger tribes also have one or two shamans in their midst. Chike are extremely territorial, generally sharing their domain only with actual crocodiles. Some tribes however do associate with marsh-dwelling races such as lizardfolk engaging in trade and allying against common enemies.\n\nChike are diurnal hunters, preferring the heat of the day vs. the cold and darkness of night. Favored meals include birds, fish, humans, goblins, and reptiles (including other chike if food truly becomes scarce). Being cold-blooded, a chike's metabolism allows it to survive up to 3 months without eating.\n\nChike males stand over 8 ft. tall while females stand just about 8 ft. tall on average. Greenish-brown scales cover the chike's back while their sides and underbellies are generally smooth and lighter in color. Chike reproduce on average once per year with the female laying up to six eggs at a time. Eggs are buried deep within their muddy lair in a special incubation hut. The female spends most of her time with the eggs until they hatch. Both the eggs and young are protected by all adults in the tribe. Females fight to the death to protect their eggs and young.\n\nChike are feared by many other races for their brutality and savagery in battle. These creatures prefer to use weapons and a fearsome bite, but particularly savage chike forego weapons and simply rend their opponents to pieces using their powerful claws. When hunting, chike submerge in water, leaving only their eyes and snout exposed. When their quarry moves within range, chike spring to attack. Though chike possess tails, they don't normally use them in combat.","ecology":"","habitat_society":""},{"name":"Chupacabra","cr":2,"xp":600,"alignment":"N","size":"Small","type":"magical beast","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":15,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+2 Dex, +2 natural, +1 size","hp":19,"hd":"3d10+3","hdvalue":3,"fort":4,"ref":5,"will":3,"speed":[{"type":"land","speed":20}],"melee":"bite +6 (1d4), 2 claws +6 (1d3 plus grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"blood drain"}],"strength":10,"dexterity":15,"constitution":12,"intelligence":2,"wisdom":11,"charisma":10,"baseatk":3,"cmb":4,"cmb_special":"+4 vs. grapple","cmd":17,"feats":[{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Perception","value":8},{"skill":"Stealth","value":14}],"environments":["warm forests","warm hills"],"organizations":["solitary","pack (2-5)"],"treasure":"none","description_visual":"This fur-covered bipedal creature is 3 or 4 ft. tall with a hunched back, red eyes, and a mouth filled with sharpened teeth. A flexible rows of spines run down its back.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Blood Drain","kind":"Ex","details":"A chupacabra can suck blood from a living creature by making a successful grapple check. If it wins the grapple check, it establishes a hold and drains blood, dealing 1d3 points of Constitution damage each round the hold is maintained."}],"description":"Chupacabras are small terrifying bloodsuckers that lurk on the fringes of society, emerging at night to drain the blood of warm-blooded creatures. Though they are not particularly selective when it comes to who or what they attack, chupacabras prefer to attack creatures they can easily kill (such as livestock or small children). Many chupacabra attacks are blamed on vampires (because of the blood drain) or wild dogs or wolves (because of the ferocity of the assault), though in the latter two cases, if the chupacabra leaves any tracks, an observer can readily tell the attacker was bipedal and moved on two legs. A chupacabra is a bipedal, almost humanoid-like creature about 3 or 4 ft. tall. It weighs 60 pounds. Its fur-covered body is dark brown or dark gray and its eyes are bright red, and often appear to be glowing. Its arms and legs end in four-clawed digits and its claws are dull black. A chupacabra cannot speak but utters a baleful moan when threatened. A chupacabra attacks with its razor-sharp claws and powerful bite, striking from ambush whenever possible. If a chupacabra grabs a foe, it slashes its throat open and sucks out its blood. If facing only one foe, a chupacabra maintains its grapple until it has drained all of its opponent's blood. When it kills an opponent, the chupacabra tears it to shreds and gorges itself on as much of the foe's blood as it can. Winged Chupacabras Rumors speak of chupacabras with fur-covered almost bat-like wings. There is a 10% chance that any chupacabra encountered is actually of the winged variety. Such a creature has a fly speed of 40 ft. with average maneuverability.","ecology":"","habitat_society":""},{"name":"Clockwork Overseer","cr":2,"xp":600,"alignment":"N","size":"Small","type":"construct","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":15,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+1 Dex, +3 natural, +1 size","hp":21,"hd":"2d10+10","hdvalue":2,"fort":0,"ref":1,"will":1,"immunities":["construct traits"],"speed":[{"type":"land","speed":40}],"melee":"slam +5 (1d6+2)","space":"5 ft.","reach":"5 ft.","strength":14,"dexterity":12,"wisdom":12,"charisma":10,"baseatk":2,"cmb":4,"cmd":15,"sq":[{"type":"independent clockwork"}],"environments":["any"],"organizations":["solitary","troupe (overseer plus clockworks of 20 HD total or less)"],"treasure":"none","description_visual":"This creature looks like a three-foot tall wooden doll with long, slender limbs. It moves with uncanny grace and a speed and fluidity that belie its mechanical origin.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Independent Clockwork","kind":"Su","details":"An overseer can move beyond the brain gear's normal area of influence while maintaining contact with it. Normally, a brain gear can control only clockworks that are within two miles of its position. A brain gear can control an overseer that stays within 10 miles of its position. In addition, the overseer can act as a field commander for up to 20 HD worth of clockworks that are within 100 ft. of its position. These clockworks are considered to be in contact with the brain gear so long as the overseer is in contact with it."}],"description":"Overseers are a recent invention of the brain gears. An overseer can journey up to 10 miles away from a brain gear while maintaining contact with it. In addition, an overseer acts as a sort of field commander for brain gears, controlling clockworks beyond the brain gear's reach. Rumors say some brain gears are researching ways to improve the overseers, hoping to extend the range at which they can operate and allow for the creation of fully functional armies that can terrorize civilized lands.\n\nAn overseer avoids direct combat at all costs under direct orders of a brain gear. If cornered with no way of escaping, an overseer fights, and attempts to flee as soon as possible.","ecology":"","habitat_society":""},{"name":"Clockwork Parasite","cr":2,"xp":600,"alignment":"N","size":"Tiny","type":"construct","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":14,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+2 natural, +2 size","hp":22,"hd":"4d10","hdvalue":4,"hp_mods":["self-repair 1 (acid, cold, fire)"],"fort":1,"ref":1,"will":0,"immunities":["construct traits"],"speed":[{"type":"land","speed":20}],"melee":"bite +7 (1d4+1)","space":"2-1/2 ft.","reach":"0 ft.","strength":12,"dexterity":10,"wisdom":8,"charisma":8,"baseatk":4,"cmb":2,"cmd":13,"cmd_special":"+8 vs. trip","sq":[{"type":"control host"}],"environments":["any"],"organizations":["horde (2-20)"],"treasure":"none","description_visual":"This creature is a fist-sized construct that resembles a mechanical beetle.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Control Host","kind":"Su","details":"By burrowing into the base of a corpse's skull and attaching itself with its pincers, a parasite clockwork can animate the creature (similar to an animate dead spell). The animated creature uses its own HD, base attack, saves, and hit points. It has an effective Wisdom of 10 and Charisma of 1. It doesn't have an Intelligence score. The host loses all skills, feats, class abilities, supernatural abilities, and spell-like abilities (including the ability to cast spells) it possessed in life. It retains its AC and any natural attacks it possessed, including proficiency with weapons. A host retains any proficiency with armor and shields it possessed while alive. Spells such as detect undead or detect magic don't reveal the presence of the parasite or host. So long as the parasite clockwork remains in contact with the host, the control remains in effect. A host brought to 0 or less hit points is destroyed, but can be repaired by the clockwork parasite using its self-repair ability (though this only works if the host is brought to 0 or less hit points; a host doesn't gain the self-repair ability of the parasite while \"alive\")."},{"type":"Self-Repair","kind":"Ex","details":"A clockwork parasite regains 1 hit point per round. Damage dealt from acid, cold, or fire effects cannot be self-repaired. If reduced to 0 or less hit points, it regains 1 hit point per round (but still cannot repair damage caused by acid, cold, or fire effects)."}],"description":"Clockwork parasites burrow into the skulls of the recently dead and reanimate the body using electrical impulses to control and direct the corpse. The animated corpses look like zombies at first glance, but a closer inspection reveals the fist-sized hole in the back of the head, wherein lurks the parasite. The host creatures, much like clockwork warriors, rely on numbers and overwhelming force to defeat their enemies. Parasites often attack from ambush, however. Parasite clockworks were designed to swarm over a battlefield, take control of the corpses lying on the field, and then ambush any enemies who moved across the field, rising from the ground to attack en masse.","ecology":"","habitat_society":""},{"name":"Clubnek","cr":2,"xp":600,"alignment":"N","size":"Medium","type":"magical beast","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":14,"ac_touch":11,"ac_flat_footed":13,"ac_mods":"+1 Dex, +3 natural","hp":19,"hd":"3d10+3","hdvalue":3,"fort":4,"ref":4,"will":1,"speed":[{"type":"land","speed":40}],"melee":"beak +5 (1d4+2), 2 claws +5 (1d4+2)","space":"5 ft.","reach":"5 ft.","strength":14,"dexterity":13,"constitution":12,"intelligence":2,"wisdom":10,"charisma":6,"baseatk":3,"cmb":5,"cmd":16,"feats":[{"feat":"Run"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Acrobatics","value":5,"special":"+9 jumping"},{"skill":"Perception","value":7},{"skill":"Stealth","value":5}],"sq":[{"type":"burst of speed"}],"environments":["temperate forests"],"organizations":["flock (2-8)"],"treasure":"none","description_visual":"This large bird resembles an ostrich with a thick neck and green-hued feathers. Its oversized beak is dark yellow.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Burst of Speed","kind":"Ex","details":"Once every 5 rounds, a clubnek can move five times its normal speed (200 ft.) when it makes a charge."}],"description":"A clubnek is a large flightless bird resembling an ostrich found roaming meadowlands and forests. It is primarily an herbivore subsisting on a diet of plants and flowers, though it is given to flights of unpredictability when it takes the role of hunter and predator.\n\nA clubnek stands 7 ft. tall and weighs about 350 pounds.\n\nClubneks are generally nonaggressive unless threatened or frightened, though they are known to occasionally have fits of erratic behavior that cause them to become quite aggressive. In such a case, they attack until slain or driven off. If its prey attempts to flee, the clubnek often runs it down and continues combat.\n\nA clubnek attacks by slashing with its claws and stabbing with its hard bony beak.","ecology":"","habitat_society":"","credit":"The Clubnek originally appeared in the First Edition Fiend Folio (© TSR/Wizards of the Coast, 1981) and is used by permission."},{"name":"Cooshee","cr":2,"xp":600,"alignment":"NG","size":"Medium","type":"magical beast","init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":16,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+3 Dex, +3 natural","hp":22,"hd":"3d10+6","hdvalue":3,"fort":5,"ref":6,"will":2,"save_mods":"+4 vs. enchantment","speed":[{"type":"land","speed":40,"special":"plus sprint"}],"melee":"Bite +6 (1d8+2 plus grab or trip), 2 claws +6 (1d4+1)","space":"5 ft.","reach":"5 ft.","strength":15,"dexterity":17,"constitution":15,"intelligence":4,"wisdom":12,"charisma":6,"baseatk":3,"cmb":5,"cmb_special":"+4 vs. grapple","cmd":18,"feats":[{"feat":"Alertness"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Perception","value":7},{"skill":"Sense Motive","value":3},{"skill":"Stealth","value":11,"special":"+15 in their natural environment"},{"skill":"Survival","value":5,"special":"+9 when tracking by scent"}],"sq":[{"type":"sprint"}],"environments":["temperate forests"],"organizations":["Solitary","pair","pack (4-9)"],"treasure":"None","description_visual":"This creature appears as a large green and brown spotted dog with slightly elven features. It has a long, curling tail and ears that taper to points above its head.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Sprint","kind":"Ex","details":"Once per hour, a cooshee can move ten times its normal speed (400 ft.) when it makes a charge attack."}],"description":"Cooshees are large, 200-pound, 4-foot tall hounds. They are known throughout the world as elven dogs, for their features resemble those of elves and they are often found in the employ of elves (who use them as guards). Though they only bark to warn their masters or other cooshees, the bark can be heard clearly up to one mile away.\n\nCooshees attack by biting and tripping their foes. Once down, an opponent is grappled and bitten.","ecology":"","habitat_society":"","credit":"The Cooshee originally appeared in Dragon #67 (© TSR/Wizards of the Coast, 1983) and later in the First Edition module S4 Lost Caverns of Tsojcanth (© TSR/Wizards of the Coast, 1982) and still later in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Crabman","cr":2,"xp":600,"alignment":"N","size":"Large","type":"monstrous humanoid","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":16,"ac_touch":9,"ac_flat_footed":16,"ac_mods":"-1 size, +7 natural","hp":19,"hd":"3d10+6","hdvalue":3,"fort":3,"ref":3,"will":3,"speed":[{"type":"land","speed":30},{"type":"swim","speed":20}],"melee":"2 claws +5 (1d6+3 plus grab)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"constrict","details":"claw 1d6+3"}],"strength":16,"dexterity":11,"constitution":15,"intelligence":10,"wisdom":10,"charisma":8,"baseatk":3,"cmb":7,"cmb_special":"+4 vs. grapple","cmd":17,"feats":[{"feat":"Alertness"},{"feat":"Power Attack"}],"skills":[{"skill":"Craft (any one)","value":6},{"skill":"Perception","value":8},{"skill":"Sense Motive","value":2},{"skill":"Survival","value":6},{"skill":"Swim","value":21}],"languages":["Crabman"],"sq":[{"type":"amphibious"}],"environments":["temperate aquatic"],"organizations":["Gang (2-12)"],"treasure":"Standard","description_visual":"This giant-sized creature is a bipedal humanoid with a crab-like head, large hands that end in powerful pincers, ft. that are splayed. It is covered with chitinous plates, reddish-brown in color. Two smaller humanoid arms protrude below its pincers.","source":"Tome of Horrors Complete (3pp)","description":"Crabmen inhabit coastal waters, hunting fish and gathering food. Crabmen communicate with others of their race through a series of hisses and clicks. A typical crabman stands about 9 ft. tall. They speak their own language, and those with an Intelligence of 12 or higher often speak common. Crabman Society Crabmen make their homes in sea caves and coastal cliffs, venturing forth occasionally in search of food. They spend most of their time hunting, filtering algae for food, or scavenging the shores and beaches. Occasionally, they will gather wet sand from the seashore and filter it through their mouths, sucking out all organic material and plankton. The remainder is a hardened, dry ball of sand approximately 1 inch across; these pellets inadvertently give away the presence of a crabman community. Crabmen live in coastal caves, but some communities will excavate more expansive burrows into the cliff face. Within such a warren, each individual has a lair set off from a centralized meeting area. Each crabman tribe is lead by an elder that can be of either sex. Most crabman tribal elders are at least 3rd-level warriors. Crabmen have no regular breeding or mating cycle, and each female seems to have her own periods of fertility and infertility. A fertile female will produce about 100 eggs within a two-week period. Crabman eggs are released into the ocean, hatching into translucent larvae with soft shells. These larvae vaguely resemble the adults, but may be mistaken for normal crabs given their size. After 6 months, crabman larvae molt and develop the harder shell required for life on land. Before their first molting, crabman larvae are practically defenseless. Crabmen rarely engage in commerce with other humanoid communities around them, including other crabman tribes. Crabman artisans produce only ephemeral goods made of driftwood, shells, and seaweed, and are quite capable of producing what other more aesthetic races would call works of art.","as_character":[{"description":"Crabmen have racial Hit Dice and can have class levels. Crabman characters possess the following traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+6 Strength, +4 Constitution, -2 Charisma. Crabmen are powerfully built but strange looking."},{"type":"Large size","value":"Crabmen are Large creatures and have the following adjustments; -1 penalty to Armor Class, -1 penalty on attack rolls, -4 penalty on Stealth checks, +1 bonus on CMB/CMD, lifting and carrying limits double those of Medium characters."},{"type":"Space/Reach","value":"10 ft./10 ft."},{"type":"Base Speed","value":"A crabman's base land speed is 30 ft. Its base swim speed is 20 ft."},{"type":"Darkvision","value":"Crabmen can see in the dark out to 60 ft."},{"type":"Racial Hit Dice","value":"A crabman begins with three levels of monstrous humanoid, which provide 3d10 HD, a base attack bonus of +3, and base saving throw bonuses of Fort +1, Ref +3, and Will +3."},{"type":"Racial Skills","value":"A crabman's monstrous humanoid levels give it skill points equal to 3 x (2 + Int modifier, minimum 1). Its class skills are Craft, Perception, and Swim. Crabmen gain a +4 Swim bonus Racial Feats: A crabman's monstrous humanoid levels give it two feats."},{"type":"AC","value":"Crabmen have a +7 natural armor bonus."},{"type":"Natural Weapons","value":"Crabmen fight with 2 claws (1d6)."},{"type":"Special Attacks","value":"Constrict, grab."},{"type":"Special Qualities","value":"Amphibious."},{"type":"Languages","value":"Crabman begin play speaking crabman. Crabmen with high intelligence scores can choose bonus languages from the following: Aquan, Common, Goblin, Sylvan."}]}],"ecology":"","habitat_society":"","credit":"The Crabman originally appeared in the First Edition Fiend Folio (© TSR/Wizards of the Coast, 1981) and is used by permission."},{"name":"Dakon","cr":2,"xp":600,"alignment":"LN","size":"Large","type":"monstrous humanoid","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":11,"ac_flat_footed":13,"ac_mods":"+2 Dex, +4 natural, -1 size","hp":15,"hd":"2d10+4","hdvalue":2,"fort":2,"ref":5,"will":5,"speed":[{"type":"land","speed":30},{"type":"climb","speed":30}],"melee":"2 claws +6 (1d6+5)","space":"10 ft.","reach":"10 ft.","strength":21,"dexterity":15,"constitution":14,"intelligence":10,"wisdom":12,"charisma":10,"baseatk":2,"cmb":5,"cmd":18,"feats":[{"feat":"Alertness"}],"skills":[{"skill":"Climb","value":18},{"skill":"Perception","value":8},{"skill":"Sense Motive","value":5},{"skill":"Stealth","value":3}],"languages":["Common"],"environments":["warm forests","warm mountains"],"organizations":["solitary","gang (2-5)","crew (7-18)","band (6-60)"],"treasure":"standard","description_visual":"This creature looks like an ape with brownish-black fur and yellow eyes with black pupils.","source":"Tome of Horrors Complete (3pp)","description":"Dakons are a race of intelligent apes that make their homes in the warmer regions of the world, though rarely, if ever, near a large expanse of water (they don't like it). They are generally friendly toward humans who share their alignment, and view all other races (even those races of the same alignment as the dakons) with caution and suspicion. Dakons stand 8 ft. tall and weigh about 500 pounds. Dakons are very passive and docile creatures; they rarely attack except in self-defense. If forced into combat, a dakon attacks with its claws.","as_character":[{"description":"Dakons have racial Hit Dice and can have class levels. Dakon characters possess the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+10 Strength, +4 Dexterity, +4 Constitution, +2Wisdom: Dakons are powerful but possessed of wisdom."},{"type":"Large size","value":"Dakons are Large and have the following adjustments -1 penalty to Armor Class, -1 penalty on attack rolls, -4 penalty on Stealth checks, +1 bonus on CMB/CMD, lifting and carrying limits double those of Medium characters."},{"type":"Space/Reach","value":"10 ft./10 ft."},{"type":"Base speed","value":"Dakons' base speed is 30 ft. A dakon has a climb speed of 30 ft."},{"type":"Darkvision","value":"Dakons can see in the dark up to 60 ft."},{"type":"Racial Hit Dice","value":"A dakon begins with two levels of monstrous humanoid, which provide 2d10 HD, a base attack bonus of +2, and base saves of Fort +0, Ref +3, and Will +3."},{"type":"Racial Skills","value":"A dakon's monstrous humanoid levels give it skill points equal to 2 x (4 + Int modifier, minimum 1). Dakons have a +8 racial bonus on Climb checks."},{"type":"Racial Feats","value":"A dakon's monstrous humanoid levels give it one feat."},{"type":"AC","value":"Dakons have a +4 natural armor bonus."},{"type":"Natural Weapons","value":"Dakons can fight with 2 claws (1d6)."},{"type":"Languages","value":"Dakons begin play speaking Common. Dakons with high Intelligence scores can choose from the following bonus languages: Dwarven, Gnome, Goblin, Orc."}]}],"ecology":"","habitat_society":"","credit":"The Dakon originally appeared in the First Edition Fiend Folio (© TSR/ Wizards of the Coast, 1981) and is used by permission."},{"name":"Dark Creeper","cr":2,"xp":600,"alignment":"CN","size":"Small","type":"humanoid","subtypes":["dark folk"],"init":3,"senses":[{"type":"see in darkness"}],"ac":16,"ac_touch":14,"ac_flat_footed":13,"ac_mods":"+2 armor, +3 Dex, +1 size, +0 natural","hp":19,"hd":"3d8+6","hdvalue":3,"fort":3,"ref":6,"will":11,"weaknesses":["light blindness"],"speed":[{"type":"land","speed":30}],"melee":"dagger +6 (1d3/19-20 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"death throes"},{"type":"sneak attack","details":"+1d6"}],"spell_like_abilities_caster_level":3,"spell_like_abilities_concentration":5,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"darkness"},{"spell":"detect magic"}]}],"strength":11,"dexterity":17,"constitution":14,"intelligence":9,"wisdom":10,"charisma":8,"baseatk":2,"cmb":15,"cmb_special":"+4 vs. grapple","cmd":31,"feats":[{"feat":"Skill Focus (Sleight of Hand)"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Climb","value":8},{"skill":"Perception","value":4},{"skill":"Sleight of Hand","value":7},{"skill":"Stealth","value":12}],"languages":["Dark Folk"],"sq":[{"type":"poison use"},{"type":"rag armor"}],"environments":["any underground"],"organizations":["solitary","pair","gang (3-6)","clan (20-80 plus 1 dark stalker per 20 dark creepers)"],"treasure":"standard","description_visual":"This creature resembles a small humanoid with a light, thin frame. It has gray skin and stark-white eyes with gray pupils. It is dressed in brownish-black filthy clothing. The smell of dung and rotted meat hangs in the air around it.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Death Throes","kind":"Su","details":"When a dark creeper is slain, its body combusts in a flash of bright white light, leaving its gear in a heap ont he ground. All creatures within a 10-foot burst must make a DC 13 Fortitude save or be blinded for 1d6 rounds. Other dark creepesr within 10 ft. are automatically blinded for at least 1 round,due to their light blindness. The save is Constitution-based."},{"type":"Poison Use","kind":"Ex","details":"Dark creepers are skilled in the use of poison and never risk accidentally poisoning themselves. Dark creepers favor a foul-smelling black paste distilled from certain deep-underground fungi known as black smear. Black Smear-injury; save Fort DC 15; frequency 1/round for 6 rounds; effect 1d2 Str; cure 1 save."},{"type":"Rag Armor","kind":"Ex","details":"A dark creeper's multiple layers of filthy rags function as leather armor when worn by one of their kind."},{"type":"See in Darkness","kind":"Su","details":"A dark creeper can see perfectly in darkness of any kind, including that created by deeper darkness."}],"description":"Dark creepers lurk in the black places deep below the surface of the world, venturing forth at night or into neighboring societies when the urge to steal and cause mayhem grows too great to resist. Endless layers of filthy, moldering black cloth shroud these small creatures, leading some to believe that the creature inside is smaller still. Usually encountered in groups, dark creepers flee from bright light, but are quite brave in the dark. Dark creepers stand just under 4 ft. tall and weigh 80 pounds. Their flesh is pale and moist, and their eyes are milky white. Dark creepers exude a foul stench of sweat and spoiled food, owing primarily to the fact that they never take off their clothing-instead piling on new layers when the outermost one grows too ragged. For all the mayhem and trouble a pack of dark creepers can cause, this isn'thing compared to the dangers a tribe led by the taller, even more sinister dark stalkers represents. Dark creepers treat their tall, lithe masters almost like gods, presenting them with offerings and obeying their every whim. Invariably, several dark stalkers serve as leaders to dark creeper tribes, with all of the tribe's heavy work and labor falling on the diminutive shoulders of the creepers, freeing the dark stalkers for their own decadent pleasures. Yet the dark creepers themselves see no inherent imbalance in this arrangement; to a dark creeper, a life in the servitude of a dark stalker is a life fulfilled. Dark Creeper Society It is known that subterranean cities of dark creepers exist. Most creatures that have seen these cities venture no closer than necessary, for the route to the city is often lined with traps, snares, and other deadly devices to detour would-be trespassers. Each city is a large circular pit with a spiraling staircase leading down to the multi-layered city. A dark creeper city is constantly shrouded in a cloud of impenetrable darkness. The actual habitat and details of dark creeper society remain a mystery, as those that have ventured into a dark creeper city have yet to return and tell of their exploits. It is believed that the race known as dark stalkers are the leaders of such cities.","as_character":[{"description":"Dark creepers possess racial Hit Dice and may have class levels. Dark Creepers have the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+6 Dexterity, +2 Constitution, +2 Wisdom, -2 Charisma: Dark creepers are quick and tough, but creepy."},{"type":"Small size","value":"Dark creepers are Small and have the following adjustments +1 bonus to Armor Class, +1 bonus on attack rolls, +4 bonus on Stealth checks, -1 penalty on CMB/CMD, lifting and carrying limits 3/4 those of Medium characters"},{"type":"Base Speed","value":"A dark creeper's base land speed is 30 ft."},{"type":"Darkvision","value":"Dark creepers can see in darkness out to 60 ft."},{"type":"Racial Hit Dice","value":"Dark creepers begin play with 3 levels of humanoid, which provides 3d8 HD, a base attack bonus of +2, and base saves of Fort +1, Ref +3, Will +1."},{"type":"Racial Skills","value":"A dark creeper's humanoid levels give it skill points equal to 3 x (2 + Int modifier, minimum 1). Dark creepers receive a +4 racial bonus on Climb, Perception and Stealth checks."},{"type":"Racial Feats","value":"A dark creeper's humanoid levels give it two feats."},{"type":"Special Attacks","value":"death throes"},{"type":"Special Qualities","value":"Light blindness, rag armor, see in darkness"},{"type":"Spell-like Abilities","value":"All dark creepers can cast darkness and detect magic at will. Their caster level equals their Hit Dice"},{"type":"Languages","value":"Dark creepers begin play speaking Dark Folk. Dark creepers with high intelligence may choose from the following bonus languages: Common, Undercommon, Goblin."}]}],"ecology":"","habitat_society":"","credit":"The Dark Creeper originally appeared in the First Edition Fiend Folio (© TSR/Wizards of the Coast, 1981) and is used by permission.","gear":"3 doses of black smear poison, dagger"}];
